            core.setOutput('is_returning_contributor', isReturningContributor);

            // Check if ok-to-test label exists
            const hasOkToTestLabel = pr.labels.some(label => label.name === 'ok-to-test');
            core.setOutput('has_ok_to_test_label', hasOkToTestLabel);

      - name: Approve workflow run
        if: |
          steps.check_contributor.outputs.is_returning_contributor == 'true' ||
          steps.check_contributor.outputs.has_ok_to_test_label == 'true'
